<script setup lang="ts">
import { router } from '@inertiajs/vue3'; import { ArrowLeft, Check, X } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import ConfirmDialog from '@/Core/Components/ConfirmDialog.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import CrmStatusBadge from '../../../Components/CrmStatusBadge.vue'; import SalesNav from '../../../Components/SalesNav.vue'; import type { SalesOrder, SalesOrderStatus } from '../../../Components/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ order: SalesOrder }>(); const { t } = useI18n(); const format = useFormat(); const action = ref<'fulfilled' | 'canceled' | null>(null); const working = ref(false); const columns = computed<Column[]>(() => [{ key: 'name', label: t('crm.fields.name') }, { key: 'quantity', label: t('crm.sales.quotes.quantity'), align: 'right' }, { key: 'price', label: t('crm.fields.unitPrice'), align: 'right' }, { key: 'total', label: t('crm.sales.quotes.total'), align: 'right' }]); function perform(): void { if (!action.value) return; working.value = true; router.patch(route('crm.sales.orders.status', { salesOrder: props.order.id }), { status: action.value as SalesOrderStatus }, { preserveScroll: true, onFinish: () => { working.value = false; action.value = null; } }); }
</script>
<template><PageHeader :eyebrow="t('crm.sales.orders.title')" :title="order.number" :description="order.company?.name ?? order.contact?.name ?? t('crm.common.notSet')"><template #actions><Button variant="ghost" :href="route('crm.sales.orders.index')"><template #icon><ArrowLeft class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.orders.title') }}</Button><Button v-if="order.editable" variant="primary" @click="action = 'fulfilled'"><template #icon><Check class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.orders.fulfil') }}</Button><Button v-if="order.editable" variant="danger" @click="action = 'canceled'"><template #icon><X class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.orders.cancel') }}</Button></template></PageHeader><SalesNav current="orders" /><div class="grid gap-3 xl:grid-cols-[minmax(0,2fr)_20rem]"><Card :title="t('crm.sales.quotes.lines')" flush><DataTable :columns="columns" :rows="order.lines" row-key="id" :caption="t('crm.sales.quotes.lines')"><template #cell-name="{ row }"><span class="font-medium text-ink">{{ row.name }}</span></template><template #cell-quantity="{ row }"><span class="tabular font-mono">{{ format.number(row.quantityMilli / 1000) }} {{ row.unit }}</span></template><template #cell-price="{ row }"><span class="tabular font-mono">{{ format.money(row.unitPriceAmount, row.currency) }}</span></template><template #cell-total="{ row }"><span class="tabular font-mono font-semibold">{{ format.money(row.lineTotalAmount, row.currency) }}</span></template></DataTable></Card><Card><div class="flex justify-between gap-3"><span class="text-ink-muted">{{ t('crm.fields.status') }}</span><CrmStatusBadge :status="order.status" /></div><dl class="mt-4 grid gap-2 text-sm"><div class="flex justify-between gap-3"><dt class="text-ink-muted">{{ t('crm.sales.quotes.subtotal') }}</dt><dd class="tabular font-mono">{{ format.money(order.subtotalAmount, order.currency) }}</dd></div><div class="flex justify-between gap-3"><dt class="text-ink-muted">{{ t('crm.sales.quotes.tax') }}</dt><dd class="tabular font-mono">{{ format.money(order.taxAmount, order.currency) }}</dd></div><div class="mt-2 flex justify-between gap-3 border-t border-line pt-3 font-semibold"><dt>{{ t('crm.sales.quotes.total') }}</dt><dd class="tabular font-mono">{{ format.money(order.totalAmount, order.currency) }}</dd></div></dl></Card></div><ConfirmDialog :open="action !== null" :title="action === 'fulfilled' ? t('crm.sales.orders.fulfil') : t('crm.sales.orders.cancel')" :description="order.number" :confirm-label="action === 'fulfilled' ? t('crm.sales.orders.fulfil') : t('crm.sales.orders.cancel')" :loading="working" @update:open="!$event && (action = null)" @confirm="perform" /></template>
